      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, an aminopyrimidine-containing kinase inhibitor, has an estimated absolute oral bioavailability of 75% in humans at a 60 mg dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam, a piperazine-containing heteroaromatic drug, has high oral bioavailability due to complete absorption and negligible intestinal and hepatic first-pass extraction in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "A structurally related N-cyclopentyl heteroaromatic compound was predicted to have a high human oral bioavailability of 80%.",
      "evidence_role": "supportive"
    }
